UNDERTAKING_HTML = '<!doctype html><html><head><meta charset="utf-8"></head><body>{% set logo = doc.company_logo or \'/assets/wafd_one/images/wafd-almadinah-official.png\' %}\n{% set beneficiary_name = doc.second_party_name or \'\' %}\n{% set beneficiary_id = doc.second_party_cr or \'\' %}\n{% set signatory = doc.authorized_signatory or doc.company_representative or \'نزار بن نذير بن ظفر\' %}\n<style>\n@page { size:A4; margin:10mm 16mm; }\nhtml,body,.print-format{margin:0!important;padding:0!important;background:#fff!important;}\n.sheet{direction:rtl;font-family:"Noto Naskh Arabic",Tahoma,Arial,sans-serif;color:#111;font-size:12px;line-height:1.65;box-sizing:border-box;min-height:267mm;padding:0;page-break-inside:avoid;}\n.head{display:table;width:100%;table-layout:fixed;border-bottom:1px solid #b88a2a;padding-bottom:3.5mm;margin-bottom:4mm;}\n.head-left,.head-right{display:table-cell;vertical-align:middle;}\n.head-left{width:35%;direction:rtl;text-align:left;font-size:10.3px;line-height:1.75;color:#444;padding-left:2mm;}\n.head-right{width:65%;text-align:right;}\n.brand{display:table;width:100%;table-layout:fixed;}\n.brand-logo,.brand-name{display:table-cell;vertical-align:middle;}\n.brand-logo{width:27mm;text-align:right;}\n.brand-name{text-align:right;padding-right:3mm;}\n.brand-name b{font-size:16px;line-height:1.45;display:block;}\n.brand-name span{font-size:9.5px;color:#666;letter-spacing:.15px;}\n.logo{width:25mm;height:25mm;object-fit:contain;}\nh1{text-align:center;font-size:18px;text-decoration:underline;margin:2mm 0 4mm;font-weight:700;}\np{margin:1.5mm 0 2.5mm;text-align:justify;font-size:12px;line-height:1.8;}\n.details{width:100%;border-collapse:collapse;margin:3mm 0;font-size:11.5px;table-layout:fixed;}\n.details td{border:1px solid #aaa;padding:2.3mm 3mm;vertical-align:top;width:50%;}\n.details b{font-size:11.8px;}\n.terms{border:1px solid #bbb;padding:2.8mm 3.2mm;margin-top:3mm;font-size:11.2px;line-height:1.65;page-break-inside:avoid;}\n.terms ol{margin:1mm 5mm 0 0;padding:0;}\n.sign{margin-top:4.5mm;text-align:center;page-break-inside:avoid;min-height:49mm;position:relative;}\n.sign-company{font-size:12px;font-weight:700;}\n.sign-title{font-size:12px;font-weight:700;margin-top:1mm;}\n.approval{position:relative;height:38mm;margin-top:0;}\n.sign-name{position:absolute;top:14mm;left:25%;right:25%;z-index:2;font-size:12.5px;font-weight:700;white-space:nowrap;}\n.signature-img{position:absolute;top:8mm;left:50%;margin-left:-24mm;width:48mm;height:19mm;object-fit:contain;z-index:3;}\n.stamp-img{position:absolute;top:20mm;left:50%;margin-left:-22mm;width:44mm;height:30mm;object-fit:contain;z-index:1;}\n.placeholder{position:absolute;top:17mm;left:35%;right:35%;border-bottom:1px solid #777;}\n</style>\n<div class=\'sheet\'>\n  <div class=\'head\'>\n    <div class=\'head-left\'>\n      <div>{{ doc.company_address or \'المدينة المنورة — حي الملك فهد\' }}</div>\n      <div dir=\'ltr\'>{{ doc.company_phone or \'0500336989\' }}</div>\n      <div dir=\'ltr\'>{{ doc.company_email or \'wafd.almadinah@gmail.com\' }}</div>\n    </div>\n    <div class=\'head-right\'>\n      <div class=\'brand\'>\n        <div class=\'brand-logo\'><img class=\'logo\' src=\'{{ logo }}\'></div>\n        <div class=\'brand-name\'><b>{{ doc.company_name or \'شركة وفد المدينة لخدمات الإعاشة\' }}</b><span>WAFD AL-MADINAH CATERING SERVICES</span></div>\n      </div>\n    </div>\n  </div>\n  <h1>تعهد والتزام إعاشة</h1>\n  <p>نحن <b>{{ doc.company_name or \'شركة وفد المدينة لخدمات الإعاشة\' }}</b>، سجل تجاري رقم <b>{{ doc.company_cr or \'7051832694\' }}</b>، نتعهد بتقديم خدمات الإعاشة للمستفيدين في الفندق الموضح أدناه، وفق البيانات المعتمدة والاشتراطات الصحية والتنظيمية، مع ضمان جودة وسلامة الوجبات أثناء التجهيز والنقل والتسليم.</p>\n  <table class=\'details\'>\n    <tr><td><b>رقم التعهد</b><br>{{ doc.name or \'\' }}</td><td><b>التاريخ</b><br>{{ doc.get_formatted(\'undertaking_date\') if doc.undertaking_date else \'\' }}</td></tr>\n    {% if doc.project %}<tr><td><b>المشروع</b><br>{{ doc.project }}</td><td><b>الفندق</b><br>{{ doc.hotel or \'\' }}</td></tr>{% else %}<tr><td colspan=\'2\'><b>الفندق</b><br>{{ doc.hotel or \'\' }}</td></tr>{% endif %}\n    <tr><td><b>اسم المستفيد</b><br>{{ beneficiary_name }}</td><td><b>رقم السجل التجاري أو الهوية للمستفيد</b><br>{{ beneficiary_id }}</td></tr>\n    <tr><td><b>عدد المستفيدين</b><br>{{ doc.beneficiary_count or 0 }}</td><td><b>الجنسية</b><br>{{ doc.nationality or \'\' }}</td></tr>\n    <tr><td><b>مدة الخدمة</b><br>{{ doc.get_formatted(\'start_date\') if doc.start_date else \'\' }} — {{ doc.get_formatted(\'end_date\') if doc.end_date else \'\' }}</td><td><b>الوجبات</b><br>{{ doc.meal_types or \'\' }}</td></tr>\n  </table>\n  <div class=\'terms\'><b>الشروط والملاحظات:</b><br><ol><li>تقديم الوجبات المتفق عليها وفق العدد ونوع الوجبة والفترة الموضحة في التعهد.</li><li>الالتزام بمواعيد تجهيز ونقل وتسليم الوجبات دون تأخير.</li><li>الالتزام باشتراطات سلامة الغذاء والنظافة والتعبئة والنقل والحفظ الحراري.</li><li>تسليم الوجبات إلى الفندق المحدد وبالكميات المعتمدة.</li><li>تزويد الفندق بالمستندات النظامية المطلوبة عند الطلب.</li><li>للفندق التحقق من الكميات والحالة الظاهرية عند الاستلام وإثبات أي ملاحظة فوراً.</li><li>لا يُعتد بأي تعديل في العدد أو المواعيد إلا بعد اعتماده من الشركة.</li></ol>{% if doc.additional_terms or doc.service_notes %}<div><b>بنود إضافية:</b> {{ doc.additional_terms or doc.service_notes }}</div>{% endif %}</div>\n  <div class=\'sign\'>\n    <div class=\'sign-company\'>شركة وفد المدينة لخدمات الإعاشة</div>\n    <div class=\'sign-title\'>{{ doc.signatory_title or \'المدير العام\' }}</div>\n    <div class=\'approval\'>\n      <div class=\'sign-name\'>{{ signatory }}</div>\n      {% if doc.include_signature and doc.signature_image %}<img class=\'signature-img\' src=\'{{ doc.signature_image }}\'>{% else %}<div class=\'placeholder\'></div>{% endif %}\n      {% if doc.include_stamp and doc.company_stamp %}<img class=\'stamp-img\' src=\'{{ doc.company_stamp }}\'>{% endif %}\n    </div>\n  </div>\n</div></body></html>'
